#define _XOPEN_SOURCE 700

#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#include "fileio.h"
#include "github.h"
#include "path.h"
#include "platform.h"
#include "rewrite.h"
#include "util.h"

static int ascii_lower(int c)
{
	return c >= 'A' && c <= 'Z' ? c - 'A' + 'a' : c;
}

/* Claude Code keeps the repository names in lower case; people may not. */
static int same_repo(const char *a, const char *b)
{
	for (; *a != '\0' && ascii_lower((unsigned char)*a) ==
	    ascii_lower((unsigned char)*b); a++, b++)
		;
	return *a == '\0' && *b == '\0';
}

/*
 * The string elements of githubRepoPaths with their states. A missing
 * .claude.json has none; -1 with errno when it cannot be read, and
 * REWRITE_INVALID when it is not valid JSON.
 */
int github_scan(const char *config_file, struct github_entry **entries,
    size_t *count)
{
	struct github_path *paths;
	char *data;
	size_t len, n, i;
	int status;

	*entries = NULL;
	*count = 0;
	if (file_read(config_file, &data, &len) != 0)
		return errno == ENOENT ? 0 : -1;
	status = config_github_paths(data, len, &paths, &n);
	free(data);
	if (status != REWRITE_OK)
		return status;
	*entries = xmalloc((n + 1) * sizeof **entries);
	for (i = 0; i < n; i++) {
		if (paths[i].path == NULL)
			continue;
		(*entries)[*count].repo = xstrdup(paths[i].repo);
		(*entries)[*count].path = xstrdup(paths[i].path);
		(*entries)[*count].state = path_state(paths[i].path,
		    platform_mount_parents);
		(*count)++;
	}
	github_paths_free(paths, n);
	return 0;
}

/* Only an orphaned path may go; an unavailable one may come back. */
size_t github_dead(const struct github_entry *entries, size_t count)
{
	size_t i, n = 0;

	for (i = 0; i < count; i++)
		if (entries[i].state == STATE_ORPHAN)
			n++;
	return n;
}

void github_entries_free(struct github_entry *entries, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++) {
		free(entries[i].repo);
		free(entries[i].path);
	}
	free(entries);
}

int github_has_repo(const struct github_entry *entries, size_t count,
    const char *repo)
{
	size_t i;

	for (i = 0; i < count; i++)
		if (same_repo(repo, entries[i].repo))
			return 1;
	return 0;
}

/*
 * Takes the orphaned paths out of githubRepoPaths: of all repositories,
 * or of the ones named. Notes say what goes and what stays; with
 * ctx->apply the file changes, with a .bak copy as in 4.4. Returns the
 * number of paths that go (or would go).
 */
size_t github_prune(struct move_ctx *ctx, char *const *repos, size_t count)
{
	struct github_path *paths;
	char *data, *out, *drop;
	size_t len, out_len, n, i, k, dropped = 0;
	int chosen;

	if (file_read(ctx->config_file, &data, &len) != 0) {
		if (errno != ENOENT)
			move_note(ctx, NOTE_ERROR, "error.read", ctx->config_file,
			    NULL, errno);
		return 0;
	}
	if (config_github_paths(data, len, &paths, &n) != REWRITE_OK) {
		move_note(ctx, NOTE_WARNING, "warn.invalid", ctx->config_file,
		    NULL, 0);
		free(data);
		return 0;
	}
	drop = xmalloc(n + 1);
	for (i = 0; i < n; i++) {
		drop[i] = 0;
		chosen = count == 0;
		for (k = 0; k < count && !chosen; k++)
			chosen = same_repo(repos[k], paths[i].repo);
		if (!chosen || paths[i].path == NULL)
			continue;
		switch (path_state(paths[i].path, platform_mount_parents)) {
		case STATE_ORPHAN:
			drop[i] = 1;
			dropped++;
			move_note(ctx, NOTE_INFO, "prune.entry", paths[i].repo,
			    paths[i].path, 0);
			break;
		case STATE_UNAVAILABLE:
			move_note(ctx, NOTE_INFO, "prune.unavailable",
			    paths[i].repo, paths[i].path, 0);
			break;
		default:
			break;
		}
	}
	if (dropped > 0) {
		config_drop_github(data, len, ctx->config_file, drop, &ctx->plan,
		    &out, &out_len);
		if (ctx->apply && out != NULL && config_write(ctx->config_file,
		    out, out_len, &ctx->backup_done) != 0)
			move_note(ctx, NOTE_ERROR, "error.file", ctx->config_file,
			    NULL, errno);
		free(out);
	}
	free(drop);
	github_paths_free(paths, n);
	free(data);
	return dropped;
}

static int is_dir(const char *path)
{
	struct stat st;

	return stat(path, &st) == 0 && S_ISDIR(st.st_mode);
}

static void add_candidate(char ***list, size_t *count, const char *old_path,
    const char *path)
{
	size_t i;

	if (strcmp(path, old_path) == 0 || !is_dir(path))
		return;
	for (i = 0; i < *count; i++)
		if (strcmp((*list)[i], path) == 0)
			return;
	*list = xrealloc(*list, (*count + 2) * sizeof **list);
	(*list)[(*count)++] = xstrdup(path);
}

static int compare_strings(const void *a, const void *b)
{
	return strcmp(*(char *const *)a, *(char *const *)b);
}

/*
 * Where a repository moved by hand may be now: first the other existing
 * paths that githubRepoPaths keeps for the same repository, then folders
 * of the same name next to the active projects. Only the name is
 * compared; the git remote is not read.
 */
char **fix_candidates(const char *old_path, const struct inventory *inv,
    const char *config_file, size_t *count)
{
	struct github_entry *entries;
	char **list = NULL, *physical, *name, *dir, *path;
	size_t n, i, k, first;

	*count = 0;
	physical = path_physical(old_path);
	if (github_scan(config_file, &entries, &n) == 0) {
		for (i = 0; i < n; i++) {
			if (strcmp(entries[i].path, old_path) != 0 &&
			    (physical == NULL ||
			    strcmp(entries[i].path, physical) != 0))
				continue;
			for (k = 0; k < n; k++)
				if (strcmp(entries[k].repo, entries[i].repo) == 0)
					add_candidate(&list, count, old_path,
					    entries[k].path);
		}
		github_entries_free(entries, n);
	}
	free(physical);
	first = *count;
	name = path_base(old_path);
	for (i = 0; i < inv->count; i++) {
		if (inv->dirs[i].state != STATE_ACTIVE)
			continue;
		dir = path_dir(inv->dirs[i].project);
		path = xjoin(dir, name);
		add_candidate(&list, count, old_path, path);
		free(path);
		free(dir);
	}
	free(name);
	if (*count > first)
		qsort(list + first, *count - first, sizeof *list,
		    compare_strings);
	return list;
}

void fix_candidates_free(char **candidates, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++)
		free(candidates[i]);
	free(candidates);
}
